const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,view='office',query='',filter='all',selected=null;
const workers=[
 {id:'scout',name:'Internship scout',short:'The scout',status:'Overnight preparation',x:20,y:43,description:'Find paid Summer 2027 roles in IB, PE, VC and M&A. Miami, NYC and Long Island first.',details:'Daily research is scheduled in your existing task. Scouts save sourced results through the local bridge; the dashboard reads the shared records. See Scout & council for actual run history and source coverage.',links:[['Handshake','https://app.joinhandshake.com/job-search'],['LinkedIn','https://www.linkedin.com/jobs/'],['Intern List','https://www.intern-list.com/accounting-and-finance-intern-list'],['YC Work at a Startup','https://www.workatastartup.com/internships']]},
 {id:'council',name:'Fit council',short:'The council',status:'Waiting for evidence',x:50,y:43,description:'Five perspectives. One unanimous decision. Every reviewed opportunity stays visible.',details:'First trial: Greystone. All five requested clarification. The reusable council workflow records independent assessments and a challenge round through this task. Realistic fit and hands-on work come first.'},
 {id:'writer',name:'Application writer',short:'The writer',status:'Practice draft ready',x:80,y:43,description:'Light wording changes, verified facts, and your approved resume layout.',details:'One Greystone practice draft is ready for document review. The original resume is preserved. No advanced Excel skills have been added.'},
 {id:'operator',name:'Application operator',short:'The applier',status:'Not connected',x:20,y:83,description:'Prepare and submit eligible applications after full verification under your standing authorization.',details:'Portal submission is not connected. You can track applications completed elsewhere. Council approval alone is not enough to submit; all application checks must pass.'},
 {id:'researcher',name:'Connection researcher',short:'Connections',status:'Ready for research',x:50,y:83,description:'UMiami alumni first, junior team members second, shared experiences third.',details:'Contact research is not automated yet. Add verified contacts and their actual connection to each opportunity.'},
 {id:'outreach',name:'Outreach writer',short:'Outreach',status:'Not connected',x:80,y:83,description:'Coffee chats, relevant introductions and thoughtful follow-ups.',details:'Draft and review messages locally. Every send needs your approval. Email and LinkedIn sending are not connected; approvals here do not send messages.'}
];
const names={office:['Good things take a team.','Your people, your pipeline, your next opportunity.','THE OFFICE'],tracker:['Your next opportunity.','Every lead stays visible. You decide what comes next.','OPPORTUNITIES'],approvals:['Your call, every time.','Review the exact draft. Nothing leaves without your say.','APPROVAL INBOX'],contacts:['A conversation can change things.','Real connections, relevant people, thoughtful follow-through.','CONNECTIONS']};
function badge(s){let cls=s.startsWith('Approved')?'approved':s==='Needs review'?'review':s==='Not approved'?'rejected':'';return `<span class="badge ${cls}">${esc(s)}</span>`}
function message(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4200)}
async function api(path,body){const opts=body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{};const r=await fetch(path,opts);const d=await r.json();if(!r.ok)throw Error(d.error||'Could not save. Your input is still here.');return d}
async function load(){const b=$('#refresh');b.classList.add('syncing');try{state=await api('/api/state');$('#error').hidden=true;render()}catch(e){$('#error').textContent='Could not reach your local workspace. '+e.message;$('#error').hidden=false}finally{b.classList.remove('syncing')}}
function navigate(v){view=v;query='';filter='all';render()}
function stats(){let approved=state.opportunities.filter(j=>j.council.startsWith('Approved')).length;let applied=state.opportunities.filter(j=>['Applied','Interviewing','Offer','Rejected'].includes(j.stage)).length;let pending=state.approvals.filter(a=>a.status==='pending'&&a.kind!=='application').length;return `<div class="stats"><div class="stat"><div class="stat-top">OPPORTUNITIES <span>↗</span></div><strong>${state.opportunities.length.toString().padStart(2,'0')}</strong><small>All research records</small></div><div class="stat"><div class="stat-top">COUNCIL APPROVED <span>◇</span></div><strong>${approved.toString().padStart(2,'0')}</strong><small>Requires all five votes</small></div><div class="stat"><div class="stat-top">APPLICATIONS SENT <span>↗</span></div><strong>${applied.toString().padStart(2,'0')}</strong><small>Confirmed or recorded by you</small></div><div class="stat accent"><div class="stat-top">NEEDS YOUR EYES <span>◉</span></div><strong>${pending.toString().padStart(2,'0')}</strong><small>Questions and reviews waiting</small></div></div>`}
function table(jobs){if(!jobs.length)return '<div class="empty"><h2>No matching opportunities</h2><p>Try another filter, or add a lead.</p></div>';return `<div class="table-wrap"><table><thead><tr><th>COMPANY / ROLE</th><th>LOCATION</th><th>APPROVAL</th><th>APPLICATION</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr tabindex="0" role="button" aria-label="Open ${esc(j.company)} opportunity" data-job="${esc(j.id)}"><td><div class="company-cell"><span class="company-monogram">${esc(j.company[0])}</span><div><strong>${esc(j.company)}</strong><small>${esc(j.title)}</small></div></div></td><td>${esc(j.location)}<small style="display:block;color:var(--muted)">${esc(j.season)}</small></td><td>${badge(j.council)}${j.user_approved?`<div style="margin-top:4px">${badge('Approved by User')}</div>`:''}${j.scout_status?`<small style="display:block;margin-top:4px">Scout: ${esc(j.scout_status==="Ready for council"?"Criteria matched":j.scout_status)}</small>`:""}</td><td>${esc(j.stage)}</td><td>↗</td></tr>`).join('')}</tbody></table></div>`}
function office(){syncWorkers();return `${stats()}${applicationFocus()}<div class="workspace"><div class="office-card"><div class="card-head"><h2>The office floor</h2><span class="caption">Select a workstation</span></div>${officeSceneMarkup()}<div class="motion-line"></div></div><div class="side-stack"><div class="sidecard pending-card"><div class="eyebrow">THE NEXT MOVE</div><h3>Ready for your review</h3><div class="big-number">${state.approvals.filter(a=>a.status==='pending'&&a.kind!=='application').length.toString().padStart(2,'0')}</div><p>Answer questions and review applications here.</p><button class="primary" data-go="approvals">Open your inbox <span style="float:right">→</span></button></div><div class="sidecard"><h3>Your application workflow</h3><div class="schedule">12–7 <span style="font-size:14px;font-weight:400">AM · Eastern</span></div><p class="meta">${esc(scoutSummary())}</p><div class="sources"><span>Handshake</span><span>LinkedIn</span><span>Intern List</span><span>YC Work at a Startup</span></div></div></div></div><div class="section-head"><h2>Next saved applications</h2><button data-go="tracker">View all opportunities ↗</button></div>${table(nextApplications().slice(0,4))}<div class="activity"><div class="eyebrow">LATEST ACTIVITY</div>${state.activity.slice(0,3).map(a=>`<div class="activity-row"><time>${new Date(a.created).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time><span>${esc(a.text)}</span></div>`).join('')}</div>`}
function tracker(){return `${stats()}<div class="toolbar"><input id="search" placeholder="Search company, role or location" aria-label="Search opportunities" value="${esc(query)}"><select id="council-filter" aria-label="Filter opportunities">${[['all','All opportunities'],['Approved','Approved (User or council)'],['Approved by User','Approved by User'],['Council approved','Council approved'],['Needs review','Needs review'],['Not approved','Not approved'],['Pending evaluation','Pending evaluation']].map(([value,label])=>`<option value="${esc(value)}" ${filter===value?'selected':''}>${label}</option>`).join('')}</select></div><div id="results">${table(filtered())}</div>`}
function filtered(){return state.opportunities.filter(j=>(filter==='all'||filter==='Approved'&&(j.user_approved||j.council.startsWith('Approved'))||filter==='Approved by User'&&j.user_approved||filter==='Council approved'&&j.council.startsWith('Approved')||j.council.startsWith(filter))&&[j.company,j.title,j.location].join(' ').toLowerCase().includes(query.toLowerCase()))}
function approvals(){return `<div class="note">Review decisions are saved locally. Application submission and message sending are not connected.</div>${state.approvals.length?`<div class="queue">${state.approvals.map(a=>`<article class="queue-card"><span class="badge ${a.status==='pending'?'review':a.status==='approved'?'approved':''}">${esc(a.status.replaceAll('_',' '))}</span><h3>${esc(a.title)}</h3><p>${a.kind==='document'?'Resume draft · Document review only':esc(a.channel)+' · '+esc(a.recipient)}</p><button class="secondary" data-approval="${a.id}">Review details →</button></article>`).join('')}</div>`:'<div class="empty"><h2>Your inbox is clear</h2><p>New documents and outreach drafts will appear here.</p></div>'}`}
function contacts(){return `<div class="section-head"><p class="caption">Alumni → Junior team members → Shared experiences</p><button class="secondary" id="add-contact">+ Add connection</button></div>${state.contacts.length?`<div class="queue">${state.contacts.map(c=>`<article class="queue-card"><span class="badge">${esc(c.group)}</span><h3>${esc(c.name)}</h3><p>${esc(c.role)} · ${esc(state.opportunities.find(j=>j.id===c.opportunity_id)?.company)}</p><p>${esc(c.connection)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">View source ↗</a><div class="actions"><button class="secondary" data-compose="${c.id}">Draft outreach</button></div></article>`).join('')}</div>`:'<div class="empty"><h2>Your network starts here.</h2><p>Add a verified contact to connect a person with an opportunity.</p></div>'}`}
function render(){if(!state)return;$('#page-title').textContent=names[view][0];$('#page-subtitle').textContent=names[view][1];$('#view-label').textContent=names[view][2];document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#job-count').textContent=state.opportunities.length;$('#approval-count').textContent=state.approvals.filter(a=>a.status==='pending'&&a.kind!=='application').length;$('#main-content').innerHTML=({office,tracker,approvals,contacts,candidate:candidateView,pipeline:pipelineView}[view])();window.officeMotion?.mount(state);}
function modal(html){$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0}
function close(){$('#dialog').close();selected=null}
function openJob(id){selected=id;const j=state.opportunities.find(j=>j.id===id);if(!j)return;modal(`<div class="eyebrow">${esc(j.company)}</div><h2 class="detail-title">${esc(j.title)}</h2><p class="detail-meta">${esc(j.location)} · ${esc(j.season)}</p>${badge(j.council)}${j.user_approved?`<p>${badge('Approved by User')} <small>${esc(j.user_approval_note||'Manual shortlist approval; council decision remains separate.')}</small></p>`:''}${researchDetail(j)}${priorCouncilDetail(j)}<div class="detail-section" style="border:0"><div class="detail-grid"><div><small>COMPENSATION</small>${esc(j.pay)}</div><div><small>LAST CHECKED</small>${esc(j.checked||'Not verified')}</div></div></div><p>${esc(j.summary)}</p><div class="actions"><a class="secondary" href="${esc(j.url)}" target="_blank" rel="noopener noreferrer">View source posting ↗</a></div><div class="detail-section" style="margin-top:20px"><h3>Next action</h3><p>${esc(j.next_action)}</p></div><details class="detail-section"><summary>Council reasoning ${j.votes.length?'· '+j.votes.filter(v=>v.vote.startsWith('Approved')).length+' / 5 approved':'· Not evaluated'}</summary>${j.votes.map(v=>`<div class="vote"><b>${esc(v.role)}</b> ${badge(v.vote)}<p>${esc(v.reason)}</p></div>`).join('')}${j.concerns.length?`<ul>${j.concerns.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:''}${j.evidence.map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.label)} ↗</a></p>`).join('')}</details>${j.documents.length?`<div class="detail-section"><h3>Application materials</h3>${j.documents.map(d=>`<a href="/documents/${d}" target="_blank">Open practice resume PDF ↗</a>`).join('')}<p style="margin-top:8px">Original resume preserved; submitted materials are recorded per application.</p></div>`:''}<div class="detail-section"><h3>Your application record</h3><form id="job-update"><label>Stage<select name="stage">${state.stages.map(s=>`<option ${j.stage===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Confirmation or evidence for an external status change<input name="evidence" placeholder="e.g. confirmation email received September 30"></label><label>Next action<input name="next_action" value="${esc(j.next_action)}"></label><label>Deadline, if verified<input type="date" name="deadline" value="${esc(j.deadline)}"></label><label>Your notes<textarea name="notes">${esc(j.notes)}</textarea></label><p class="form-error" hidden></p><button class="primary">Save record</button></form></div><div class="actions"><button class="secondary" data-contact-job="${j.id}">Add connection</button><button class="secondary" data-draft-job="${j.id}">Draft outreach</button></div>${j.history.length?`<div class="detail-section"><h3>Recorded history</h3>${j.history.map(h=>`<p>${esc(h.stage)} — ${esc(h.evidence)} <small>Recorded by ${esc(h.recorded_by)}</small></p>`).join('')}</div>`:''}`);$('#job-update').onsubmit=e=>submit(e,'/api/opportunity/update',{id:j.id},()=>{message('Application record saved.');openJob(j.id)})}
function worker(id){const w=workers.find(w=>w.id===id);modal(`<div class="eyebrow">YOUR TEAM</div><h2 class="detail-title">${w.name}</h2>${badge(w.status)}<div class="detail-section" style="margin-top:20px"><p>${w.description}</p></div><div class="note">${w.details}</div>${w.links?`<div class="actions">${w.links.map(([l,u])=>`<a class="secondary" href="${u}" target="_blank" rel="noopener noreferrer">${l} ↗</a>`).join('')}</div>`:''}<div class="actions"><button class="primary" data-worker-view="${id==='writer'||id==='outreach'?'approvals':id==='researcher'?'contacts':'pipeline'}">Open workspace →</button></div>`)}
function addJob(){modal(`<div class="eyebrow">ADD TO YOUR RADAR</div><h2 class="detail-title">A new opportunity</h2><p class="detail-meta">Save the source. Verify before shortlisting.</p><form id="new-job"><div class="grid2"><label>Company<input name="company" required maxlength="150"></label><label>Role<input name="title" required maxlength="300"></label></div><label>Source URL<input name="url" type="url" required placeholder="https://..."></label><div class="grid2"><label>Location<input name="location" placeholder="New York, NY"></label><label>Season<input name="season" value="Summer 2027"></label><label>Pay<input name="pay" placeholder="Unknown until verified"></label><label>Source<input name="source" placeholder="Employer, Handshake, LinkedIn..."></label></div><label>Role summary<textarea name="summary"></textarea></label><p class="form-error" hidden></p><button class="primary">Add opportunity</button></form>`);$('#new-job').onsubmit=e=>submit(e,'/api/opportunities',{},()=>{close();navigate('tracker');message('Opportunity added. Council evaluation pending.')})}
function jobOptions(id){return state.opportunities.map(j=>`<option value="${j.id}" ${j.id===id?'selected':''}>${esc(j.company)} — ${esc(j.title)}</option>`).join('')}
function addContact(job){modal(`<div class="eyebrow">CONNECTION RESEARCH</div><h2 class="detail-title">Add a verified connection</h2><form id="contact-form"><label>Opportunity<select name="opportunity_id">${jobOptions(job)}</select></label><div class="grid2"><label>Name<input name="name" required></label><label>Role / team<input name="role"></label></div><label>Profile or evidence URL<input name="url" type="url" required></label><label>Connection group<select name="group"><option>UMiami alumni</option><option>Junior team member</option><option>Shared experience</option><option>Existing connection</option></select></label><label>Verified common ground<textarea name="connection" placeholder="What you actually share, and how you know."></textarea></label><p class="form-error" hidden></p><button class="primary">Save connection</button></form>`);$('#contact-form').onsubmit=e=>submit(e,'/api/contacts',{},()=>{close();navigate('contacts');message('Connection saved.')})}
function compose(job,contact){modal(`<div class="eyebrow">OUTREACH DRAFT</div><h2 class="detail-title">Start a conversation.</h2><p class="detail-meta">Saved locally for your review. Sending is not connected.</p><form id="outreach-form"><label>Opportunity<select name="opportunity_id">${jobOptions(job)}</select></label><div class="grid2"><label>Recipient or profile<input name="recipient" required value="${esc(contact?.name||'')}"></label><label>Channel<select name="channel"><option>Email</option><option>LinkedIn</option></select></label></div><label>Subject / draft title<input name="title" required></label><label>Exact message<textarea name="body" required style="min-height:190px"></textarea></label><p class="form-error" hidden></p><button class="primary">Queue for review</button></form>`);$('#outreach-form').onsubmit=e=>submit(e,'/api/outreach',{},()=>{close();navigate('approvals');message('Draft queued. Nothing sent.')})}
function review(id){const a=state.approvals.find(a=>a.id===id);modal(`<div class="eyebrow">${a.kind==='document'?'DOCUMENT REVIEW':'MESSAGE REVIEW'}</div><h2 class="detail-title">${esc(a.title)}</h2>${badge(a.status.replaceAll('_',' '))}<div class="detail-section" style="margin-top:20px">${a.kind==='document'?`<p>${esc(a.body)}</p><div class="actions"><a class="secondary" href="/documents/${a.document_id}" target="_blank">Read the PDF ↗</a></div>`:`<div class="detail-grid"><div><small>RECIPIENT</small>${esc(a.recipient)}</div><div><small>CHANNEL</small>${esc(a.channel)}</div></div><div class="message-body" style="margin-top:20px">${esc(a.body)}</div>`}</div><div class="note">${a.kind==='document'?'This approves this document version only. The application still needs every eligibility, completeness and submission check.':'This records approval of this exact message. Sending is not connected, so nothing will be sent.'}</div>${a.status==='pending'?`<label><input id="review-check" type="checkbox" style="width:auto;display:inline;margin-right:8px">I reviewed this exact ${a.kind==='document'?'document':'recipient and message'}.</label><p class="form-error" hidden></p><div class="actions"><button class="primary" id="approve" disabled>Approve ${a.kind==='document'?'document':'message'}</button><button class="secondary" id="request-changes">Request changes</button></div>`:''}`);if(a.status!=='pending')return;$('#review-check').onchange=e=>$('#approve').disabled=!e.target.checked;const decide=async decision=>{try{await api('/api/approval',{id:a.id,fingerprint:a.fingerprint,decision});await load();review(a.id);message('Decision saved. Nothing submitted or sent.')}catch(e){const el=$('#dialog .form-error');el.hidden=false;el.textContent=e.message}};$('#approve').onclick=()=>decide('approved');$('#request-changes').onclick=()=>decide('changes_requested')}
async function submit(e,path,extra,success){e.preventDefault();const form=e.target;const b=form.querySelector('button[type=submit]')||form.querySelector('button');b.disabled=true;try{await api(path,{...Object.fromEntries(new FormData(form)),...extra});await load();success()}catch(err){const el=form.querySelector('.form-error');el.hidden=false;el.textContent=err.message}finally{b.disabled=false}}
document.addEventListener('click',e=>{let t=e.target.closest('[data-view],[data-go],[data-job],[data-worker],[data-approval],[data-worker-view],[data-contact-job],[data-draft-job],[data-compose]');if(!t)return;if(t.dataset.view||t.dataset.go)navigate(t.dataset.view||t.dataset.go);if(t.dataset.job)openJob(t.dataset.job);if(t.dataset.worker)worker(t.dataset.worker);if(t.dataset.approval)review(t.dataset.approval);if(t.dataset.workerView){close();navigate(t.dataset.workerView)}if(t.dataset.contactJob)addContact(t.dataset.contactJob);if(t.dataset.draftJob)compose(t.dataset.draftJob);if(t.dataset.compose){const c=state.contacts.find(c=>c.id===t.dataset.compose);compose(c.opportunity_id,c)}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('tr[data-job]')){e.preventDefault();openJob(e.target.dataset.job)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#results').innerHTML=table(filtered())}});document.addEventListener('change',e=>{if(e.target.id==='council-filter'){filter=e.target.value;$('#results').innerHTML=table(filtered())}});document.addEventListener('click',e=>{if(e.target.id==='add-contact')addContact()});
$('#dialog .close').onclick=close;$('#add-job').onclick=addJob;$('#refresh').onclick=load;$('#export').onclick=async()=>{try{const d=await api('/api/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='internship-office-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){message(e.message)}};
// Read-only agent tools; approvals intentionally stay in the human review UI.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [
{name:'list_internship_records',description:'Read local internship records and council signals. Does not search, apply, or send.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(Object.keys(input).length)throw Error('No inputs accepted.');const s=await api('/api/state');return s.opportunities.map(({id,company,title,council,stage,next_action})=>({id,company,title,council,stage,next_action}))}},
{name:'open_internship_record',description:'Open an existing opportunity detail panel. Does not modify records or grant approval.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(typeof input.id!=='string'||Object.keys(input).length!==1||!state.opportunities.some(j=>j.id===input.id))throw Error('Unknown opportunity.');openJob(input.id);return {opened:input.id}}}
]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
